const { state, sort, maxResults } = $.input;
const params = {};
params.state = state || 'open';
params.sort = sort || 'created';
params.per_page = String(Math.max(1, Math.min(30, maxResults || 5)));
return { params };

const resp = $.steps.listPRs.response || [];
const prs = Array.isArray(resp) ? resp : [];
return { prs, count: prs.length };

const pr = $.steps.getPR?.response || $.loop.pr;
const reviews = $.steps.getReviews?.response || [];

const reviewList = (Array.isArray(reviews) ? reviews : []).map(r => ({
  user: r.user?.login || 'unknown',
  state: r.state,
  submittedAt: r.submitted_at
}));

const latestByUser = {};
reviewList.forEach(r => {
  if (!latestByUser[r.user] || new Date(r.submittedAt) > new Date(latestByUser[r.user].submittedAt)) {
    latestByUser[r.user] = r;
  }
});

const approved = Object.values(latestByUser).filter(r => r.state === 'APPROVED').length;
const changesRequested = Object.values(latestByUser).filter(r => r.state === 'CHANGES_REQUESTED').length;

return {
  number: pr.number,
  title: pr.title,
  state: pr.state,
  draft: pr.draft || false,
  author: pr.user?.login || 'unknown',
  head: pr.head?.ref || '',
  base: pr.base?.ref || '',
  additions: pr.additions || 0,
  deletions: pr.deletions || 0,
  changedFiles: pr.changed_files || 0,
  mergeable: pr.mergeable,
  mergeableState: pr.mergeable_state || '',
  labels: (pr.labels || []).map(l => l.name || l),
  assignees: (pr.assignees || []).map(a => a.login),
  reviewSummary: { approved, changesRequested, total: reviewList.length },
  reviews: reviewList,
  createdAt: pr.created_at,
  updatedAt: pr.updated_at,
  url: pr.html_url
};

const iterations = $.steps.fetchDetails?.response?.iterations || [];
const prs = iterations.map(r => r?.parsePR?.output).filter(Boolean);

return {
  pullRequests: prs,
  totalFound: prs.length,
  repo: $.input.owner + '/' + $.input.repo,
  filters: { state: $.input.state || 'open' },
  summary: 'Found ' + prs.length + ' pull request' + (prs.length === 1 ? '' : 's') + ' in ' + $.input.owner + '/' + $.input.repo
};
